def facts():
    cores, start, trips = KV.split(12, 3)
    covered = True
    for vc in range(1, 5):
        for n in range(34):
            p, first, count = KV.split(n, vc)
            rows = [first(c) + i for c in range(p) for i in range(count(c))]
            covered &= p == max(1, min(n, vc)) and sorted(rows) == list(range(n))
    return {"cores": cores, "covered": covered}
